cards.solution:
// === keranjang.js ===
export default class Keranjang {
  constructor() {
    this.item = [];
  }
  tambah(nama) {
    this.item.push(nama);
    return this;
  }
}
// === main.js ===
import Keranjang from "./keranjang.js";
const k = new Keranjang().tambah("Kopi").tambah("Roti");
console.log(k.item.join(", "));
